export type AppRequest = LoadRequest | LoadHtmlRequest | BackRequest | ForwardRequest | ReloadRequest | ClickAtRequest | SetViewportRequest | ScrollRequest | HitTestRequest | CommitTextRequest | PumpRequest | GetFrameRequest | GetNavRequest | PingRequest | ExportSessionStorageRequest | ImportSessionStorageRequest | ExportHistoryRequest | ImportHistoryRequest | DeliverMessageRequest | DisposeRequest;
export type AppReply = FrameReply | HitInfoReply | PumpReply | FrameBytesReply | NavStateReply | ClickReply | SessionStorageReply | HistoryReply | StatusReply | Error;

/** Encode [u32 len][u64 requestId][u16 tag][payload]. */
export function encodeRequest(requestId: number, msg: AppRequest): ArrayBuffer {
  const w = new Writer();
  w.u32(0);
  w.u64(requestId);
  const tag: number = MessageTag[msg.kind as keyof typeof MessageTag];
  w.u16(tag);
  switch (msg.kind) {
    case "load": writeLoad(w, msg); break;
    case "loadHtml": writeLoadHtml(w, msg); break;
    case "back": writeBack(w, msg); break;
    case "forward": writeForward(w, msg); break;
    case "reload": writeReload(w, msg); break;
    case "clickAt": writeClickAt(w, msg); break;
    case "setViewport": writeSetViewport(w, msg); break;
    case "scroll": writeScroll(w, msg); break;
    case "hitTest": writeHitTest(w, msg); break;
    case "commitText": writeCommitText(w, msg); break;
    case "pump": writePump(w, msg); break;
    case "getFrame": writeGetFrame(w, msg); break;
    case "getNav": writeGetNav(w, msg); break;
    case "ping": writePing(w, msg); break;
    case "exportSessionStorage": writeExportSessionStorage(w, msg); break;
    case "importSessionStorage": writeImportSessionStorage(w, msg); break;
    case "exportHistory": writeExportHistory(w, msg); break;
    case "importHistory": writeImportHistory(w, msg); break;
    case "deliverMessage": writeDeliverMessage(w, msg); break;
    case "dispose": writeDispose(w, msg); break;
  }
  w.patchU32(0, w.length);
  return w.finish();
}

export function decodeRequest(buf: ArrayBuffer | Uint8Array): { requestId: number; msg: AppRequest } {
  const r = new Reader(buf);
  const totalLen = r.u32();
  const requestId = r.u64();
  const tag = r.u16();
  if (totalLen !== r.size) throw new Error(`ipc: frame length ${totalLen} != buffer ${r.size}`);
  let msg: AppRequest;
  switch (tag) {
    case 1: msg = readLoad(r); break;
    case 2: msg = readLoadHtml(r); break;
    case 3: msg = readBack(r); break;
    case 4: msg = readForward(r); break;
    case 5: msg = readReload(r); break;
    case 6: msg = readClickAt(r); break;
    case 7: msg = readSetViewport(r); break;
    case 8: msg = readScroll(r); break;
    case 9: msg = readHitTest(r); break;
    case 10: msg = readCommitText(r); break;
    case 11: msg = readPump(r); break;
    case 12: msg = readGetFrame(r); break;
    case 13: msg = readGetNav(r); break;
    case 14: msg = readPing(r); break;
    case 15: msg = readExportSessionStorage(r); break;
    case 16: msg = readImportSessionStorage(r); break;
    case 17: msg = readExportHistory(r); break;
    case 18: msg = readImportHistory(r); break;
    case 19: msg = readDeliverMessage(r); break;
    case 20: msg = readDispose(r); break;
    default: throw new Error(`ipc: unknown request tag ${tag}`);
  }
  if (r.remaining !== 0) throw new Error(`ipc: trailing bytes in request tag ${tag}`);
  return { requestId, msg };
}

export function encodeReply(requestId: number, msg: AppReply): ArrayBuffer {
  const w = new Writer();
  w.u32(0);
  w.u64(requestId);
  const tag: number = MessageTag[msg.kind as keyof typeof MessageTag];
  w.u16(tag);
  switch (msg.kind) {
    case "frameReply": writeFrameReply(w, msg); break;
    case "hitInfoReply": writeHitInfoReply(w, msg); break;
    case "pumpReply": writePumpReply(w, msg); break;
    case "frameBytesReply": writeFrameBytesReply(w, msg); break;
    case "navStateReply": writeNavStateReply(w, msg); break;
    case "clickReply": writeClickReply(w, msg); break;
    case "sessionStorageReply": writeSessionStorageReply(w, msg); break;
    case "historyReply": writeHistoryReply(w, msg); break;
    case "statusReply": writeStatusReply(w, msg); break;
    case "error": writeError(w, msg); break;
  }
  w.patchU32(0, w.length);
  return w.finish();
}

export function decodeReply(buf: ArrayBuffer | Uint8Array): { requestId: number; msg: AppReply } {
  const r = new Reader(buf);
  const totalLen = r.u32();
  const requestId = r.u64();
  const tag = r.u16();
  if (totalLen !== r.size) throw new Error(`ipc: frame length ${totalLen} != buffer ${r.size}`);
  let msg: AppReply;
  switch (tag) {
    case 21: msg = readFrameReply(r); break;
    case 22: msg = readHitInfoReply(r); break;
    case 23: msg = readPumpReply(r); break;
    case 24: msg = readFrameBytesReply(r); break;
    case 25: msg = readNavStateReply(r); break;
    case 26: msg = readClickReply(r); break;
    case 27: msg = readSessionStorageReply(r); break;
    case 28: msg = readHistoryReply(r); break;
    case 29: msg = readStatusReply(r); break;
    case 0: msg = readError(r); break;
    default: throw new Error(`ipc: unknown reply tag ${tag}`);
  }
  if (r.remaining !== 0) throw new Error(`ipc: trailing bytes in reply tag ${tag}`);
  return { requestId, msg };
}
